import fs from 'node:fs';import assert from 'node:assert/strict';import {execFileSync} from 'node:child_process';
import {hash,json} from './bounded-source-hash-20261026.mjs';import {guarded} from './run-small-native-task-guarded-20261025.mjs';
const site='F:/VisibleMedicine/staging/20261027-tour-step-native/atlas',dir='F:/VisibleMedicine/staging/20261027-current-teaching-inventory';
const git=(...args)=>execFileSync('git',args,{cwd:site,encoding:'utf8',windowsHide:true}).trim();
const head='5c7346af577ae626c1ac06c0352f96bf84d36100';assert.equal(git('rev-parse','HEAD'),head);assert.equal(git('status','--porcelain'),'');
const ix=json('CURRENT_CHECKPOINT.json');assert.deepEqual(ix.activeWork.current.activeExecutionSessions,[]);ix.activeWork.current.activeExecutionSessions=[{kind:'readonly-teaching-inventory',driverPid:process.pid,evidence:dir}];fs.writeFileSync('CURRENT_CHECKPOINT.json',JSON.stringify(ix,null,2)+'\n');
const retire=()=>{const i=json('CURRENT_CHECKPOINT.json');i.activeWork.current.activeExecutionSessions=i.activeWork.current.activeExecutionSessions.filter(s=>s.driverPid!==process.pid);fs.writeFileSync('CURRENT_CHECKPOINT.json',JSON.stringify(i,null,2)+'\n');};const early=()=>{if(!fs.existsSync(dir+'/SUPERVISOR-HANDLE.json'))retire();};process.once('exit',early);
try{global.gc();const run=await guarded({site,dir,command:'--max-old-space-size=1024 scripts/report-teaching-gaps.mjs --region=head-neck',heap:1024,aggregate:2048,minimum:4096});assert(run.passing);assert.equal(git('rev-parse','HEAD'),head);assert.equal(git('status','--porcelain'),'');const report=JSON.parse(fs.readFileSync(dir+'/runner.stdout.log','utf8'));assert.equal(report.evidence.sourceRevision,head);assert.equal(report.evidence.workingTreeDirty,false);const result={at:new Date().toISOString(),run,report:{path:dir+'/runner.stdout.log',sha256:hash(dir+'/runner.stdout.log')},sourceUnchanged:true,passing:true,clinicalApproval:false};fs.writeFileSync(dir+'/RESULT.json',JSON.stringify(result,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({path:dir+'/RESULT.json',sha256:hash(dir+'/RESULT.json'),rows:report.rows.length}));}finally{process.removeListener('exit',early);retire();}
